## Hint 1

There are four ways a worker can end your wait and only one of them is the one
you were hoping for. Write the four down before you write any code, then note
that whichever fires first is the answer and the rest are noise.

The shape is the classic promise-around-an-emitter from `04_events_errors`,
with twice as many exits.

## Hint 2

A settle-once guard plus a single cleanup function is the pattern:

```ts
let done = false;
const finish = (fn: () => void) => {
  if (done) return;
  done = true;
  cleanup();
  fn();
};
```

Note the ordering: cleanup runs *before* you resolve, so nothing you detach
can be triggered by a listener that runs during settlement.

## Hint 3

Register `message`, `error`, `messageerror` and `exit` with `worker.on`, keep
named handler functions so `worker.off` can match them by identity, and let
the `exit` handler reject — it can only reach the reject path if the guard is
still open, which by definition means nothing else settled first.

The decision left to you: whether to `terminate()` on the success path too.
Consider what happens when the worker posts its answer and then keeps running.

references.solution.ts:
// v3nc01_worker_threads / ex1 - reference solution (author only, used by `dojo verify`).
import { Worker } from "node:worker_threads";

export function runOnce<T>(source: string, workerData?: unknown): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const worker = new Worker(source, { eval: true, workerData });

    let settled = false;
    const cleanup = (): void => {
      worker.off("message", onMessage);
      worker.off("error", onError);
      worker.off("messageerror", onMessageError);
      worker.off("exit", onExit);
    };
    const settle = (action: () => void): void => {
      if (settled) return;
      settled = true;
      cleanup();
      action();
    };

    const onMessage = (value: T): void =>
      settle(() => {
        // The answer is in; the thread is of no further use to anyone.
        void worker.terminate();
        resolve(value);
      });
    const onError = (error: Error): void => settle(() => reject(error));
    const onMessageError = (error: Error): void =>
      settle(() =>
        reject(new Error("worker sent a value that could not be deserialised (messageerror)", { cause: error })),
      );
    // Only reachable when nothing else settled first: the silent-exit hang.
    const onExit = (code: number): void =>
      settle(() => reject(new Error(`worker exited with code ${code} before sending a message`)));

    worker.on("message", onMessage);
    worker.on("error", onError);
    worker.on("messageerror", onMessageError);
    worker.on("exit", onExit);
  });
}

// v3nc01_worker_threads / ex2 - reference solution (author only, used by `dojo verify`).

export interface Partition {
  readonly start: number;
  readonly end: number;
}

export function planPartitions(length: number, workers: number): Partition[] {
  if (!Number.isInteger(length) || length < 0) {
    throw new RangeError(`length must be a non-negative integer, got ${length}`);
  }
  if (!Number.isInteger(workers) || workers < 1) {
    throw new RangeError(`workers must be a positive integer, got ${workers}`);
  }

  // Never plan more partitions than there are items: an empty range is a
  // thread that starts, allocates an isolate and does nothing.
  const count = Math.min(workers, length);
  const base = Math.floor(length / count || 1);
  const remainder = count === 0 ? 0 : length % count;

  const partitions: Partition[] = [];
  let cursor = 0;
  for (let i = 0; i < count; i++) {
    // The first `remainder` partitions carry the extra item each, which keeps
    // the largest and smallest partitions within one item of each other.
    const size = base + (i < remainder ? 1 : 0);
    partitions.push({ start: cursor, end: cursor + size });
    cursor += size;
  }
  return partitions;
}

