## Problem 3 — a parallel map that keeps its order

Edit `ex3/solution.ts`. Implement:

```ts
export function sumInWorkers(values: number[], workers: number): Promise<{
  total: number;
  partials: number[];
}>
```

Split `values` into balanced partitions (the ex2 rule), run **one worker per
partition** with `{ eval: true }`, and have each worker post the sum of its
slice. `partials` must be in partition order — the order of the input, not the
order the workers finished in — and `total` is their sum.

An empty `values` resolves to `{ total: 0, partials: [] }` without spawning
anything. If any worker fails, the returned promise rejects and no worker is
left running.

```ts
await sumInWorkers([1, 2, 3, 4, 5], 2);
// { total: 15, partials: [6, 9] }
```

```
uv run dojo test node v3nc01_worker_threads ex3
```

references.solution.ts:
// v3nc01_worker_threads / ex3 - reference solution (author only, used by `dojo verify`).
import { Worker } from "node:worker_threads";

const SOURCE = `
const { parentPort, workerData } = require("node:worker_threads");
let sum = 0;
for (const n of workerData.chunk) sum += n;
parentPort.postMessage(sum);
`;

function plan(length: number, workers: number): Array<[number, number]> {
  const count = Math.min(workers, length);
  const ranges: Array<[number, number]> = [];
  let cursor = 0;
  for (let i = 0; i < count; i++) {
    const size = Math.floor(length / count) + (i < length % count ? 1 : 0);
    ranges.push([cursor, cursor + size]);
    cursor += size;
  }
  return ranges;
}

export async function sumInWorkers(
  values: number[],
  workers: number,
): Promise<{ total: number; partials: number[] }> {
  const ranges = plan(values.length, workers);
  if (ranges.length === 0) return { total: 0, partials: [] };

  const live: Worker[] = [];
  try {
    // Built in partition order, so Promise.all hands back partition order -
    // completion order never gets a vote.
    const jobs = ranges.map(([start, end]) => {
      const worker = new Worker(SOURCE, {
        eval: true,
        workerData: { chunk: values.slice(start, end) },
      });
      live.push(worker);
      return new Promise<number>((resolve, reject) => {
        worker.once("message", resolve);
        worker.once("error", reject);
        worker.once("exit", (code) => {
          if (code !== 0) reject(new Error(`partition worker exited with code ${code}`));
        });
      });
    });

    const partials = await Promise.all(jobs);
    return { total: partials.reduce((a, b) => a + b, 0), partials };
  } finally {
    // Promise.all rejects on the first failure but cancels nothing; without
    // this the surviving threads keep the process alive.
    await Promise.all(live.map((worker) => worker.terminate()));
  }
}

